"""Layer 15 MLP unit 4867 (read by component p-82af68dd@100000/layers.15.mlp.down_proj:4867).

What it does, in plain terms: this component goes negative on a finite verb helper
(a modal such as "will", "can", "may", or a form of "be", "have", "do") that comes
right after a noun subject, as in "the approach [is]", "the stream [is]", "a tail
[will]". After a pronoun subject ("it is", "this can") it is close to zero, and
elsewhere it is slightly negative for modals and nearly zero for other tokens.

Only the helper verb's own position is predicted; everything else predicts 0. The
numbers are the mean activations on training text, rounded.
"""

import functools

import wordnet

READS = ()

MODALS = {"will", "would", "can", "could", "may", "might", "shall", "should", "must"}
HELPERS = {"is", "are", "was", "were", "has", "have", "had", "does", "did", "do", "am"}
PRONOUNS = {
    "it", "he", "she", "they", "we", "you", "i", "this", "that", "these", "those",
    "who", "which", "there", "what", "one",
}


@functools.lru_cache(maxsize=None)
def is_noun_subject(word):
    """A word that can head a noun subject: WordNet lists it as a noun, and it is not a pronoun."""
    return word.isalpha() and word not in PRONOUNS and "noun" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    after_noun = is_noun_subject(before)
    if word in MODALS:
        return carry, -1.1 if after_noun else -0.35
    if word in HELPERS:
        return carry, -0.6 if after_noun else -0.2
    return carry, 0.0

"""Layer 15 MLP hidden unit 4880 (down_proj component): "what is being counted or measured".

The unit is quiet almost everywhere. It switches on at the token right after a number,
the word or symbol that names the quantity: "12 km", "3 million", "40 %", "two miles".
Its strongest responses are to units of measure and scale words (km, mg, million,
percent, miles); other words after a number respond weakly, and a decimal point
after a number responds slightly negatively. Digits that continue a number are slightly
negative. Everywhere else it predicts 0.

The program is stateless: it reads only the current token and the one before it,
and treats a new document as starting with no number.
"""

READS = ()

NUMBER_WORDS = set(
    "one two three four five six seven eight nine ten eleven twelve twenty thirty forty "
    "fifty sixty seventy eighty ninety hundred thousand million billion dozen".split()
)

UNITS = set(
    "km cm mm nm µm μm m kg g mg µg μg pg ng mL ml L l ms s sec min h hr "
    "mi miles mile ft feet inch inches lb lbs pounds oz ounces tons tonnes acres "
    "cups litres liters kB KB MB GB Hz kHz MHz GHz kW W V mV mA A "
    "% ° percent dollars USD euros years days hours weeks months minutes seconds "
    "people patients participants pages views times units "
    "million billion thousand trillion mil ppm kilometres kilometers meters metres grams".split()
)

NUMBER_ISH = {
    *(str(d) for d in range(10)),
}


def _word(s):
    return s.strip().lower()


def _is_number(s):
    return s in NUMBER_ISH or _word(s) in NUMBER_WORDS


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    if cur in NUMBER_ISH and prev in NUMBER_ISH:
        return carry, -0.3  # a digit inside a number
    if not _is_number(prev):
        return carry, 0.0
    if cur.strip() in UNITS:
        return carry, 3.6  # unit or scale word after a number: "12 km", "3 million"
    if cur.strip() == ".":
        return carry, -0.4  # decimal point or full stop after a number
    if cur.strip().isalpha():
        return carry, 1.0  # another word after a number
    return carry, 0.5  # punctuation, space or symbol after a number

"""Layer 15 MLP down-projection component 4890: a weak, mostly context-driven direction.

What it does: its activation averages about -0.085 with spread about 0.41, and it is
most negative on a few word classes. Read as a rule, it predicts:
  - "by" (as in "paid by", "sponsored by", "popularized by"): about -0.29, its most
    negative common word;
  - quantifiers and determiners that follow a preposition ("other", "all", "this",
    "each", "both", "entire"): about -0.19;
  - prepositions and conjunctions ("of", "to", "in", "and", "as"): about -0.10;
  - everything else, including articles and punctuation: the mean, -0.085.

Honest limits: these word classes explain under 1% of the held-out variance. The
activation depends on context the rule cannot see, so most of its spread stays unexplained.
Its contribution to the residual stream is tiny, and the model barely depends on it.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MEAN = -0.085
BY = {"by"}
QUANTIFIERS = {"this", "all", "other", "each", "both", "every", "entire", "some", "any",
               "one", "these", "those"}
PREPOSITIONS = {"of", "to", "in", "for", "with", "as", "between", "against", "on",
                "from", "at", "and", "or"}


def step(carry, prefix, upstream: Mapping):
    """Read the newest token's word and return the class's typical activation."""
    word = prefix.token_strings[-1].strip().lower()
    if word in BY:
        value = -0.29
    elif word in QUANTIFIERS:
        value = -0.19
    elif word in PREPOSITIONS:
        value = -0.10
    else:
        value = MEAN
    return carry, value

"""Shift-of-focus detector for component 4892 of layers.15.mlp.down_proj.

What it responds to: running text in which attention or motion is turned onto a new topic or
back to an old one. The strongest values are on "focus" and its forms. Next come "back" (as in
"go back to", "step back"), the verbs that begin or move something ("begin", "start", "shift",
"move on", "proceed", "talk about"), and the preposition that completes such a move ("to",
"towards", "on", "from", "with") when a motion or focus word came just before it.

Passive or static description pushes it below its resting value: the participles "known",
"named", "composed", "graduated", "divided", "defined", "located" themselves, and a preposition
right after a "be" verb or a passive participle ("is divided into", "graduated from").

Everywhere else it sits near its resting value, about -0.07. The program captures only the
large, sparse part of the activation. Most of its variance is spread thinly over ordinary
tokens, and no simple word or context rule here captures it.
"""

READS = ()

RESTING = -0.07
FOCUS = {"focus", "focuses", "focused", "focusing"}
MOTION = {
    "begin", "begins", "began", "start", "starts", "started", "starting", "continue",
    "continued", "proceed", "proceeds", "resume", "resumed", "shift", "shifts", "shifted",
    "shifting", "move", "moves", "moved", "moving", "transition", "transitions", "turn",
    "turned", "turning", "turns", "talk", "talks", "talked", "extend", "extended",
    "concentrate", "concentrated", "drift", "drifted", "returning", "returned", "go",
    "going", "goes", "went", "venture", "step", "stepped",
}
PARTICLES = {"to", "back", "on", "into", "towards", "toward", "from", "away", "forward",
             "further", "farther", "with", "about", "up", "out"}
PASSIVE = {"known", "named", "composed", "graduated", "divided", "defined", "located"}
BE = {"is", "was", "are", "were", "be", "been", "being"}


def word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    here = word(tokens[-1])
    # the words just before this one, within the same document
    before = []
    for i in range(len(tokens) - 2, max(-1, len(tokens) - 4), -1):
        if docs[i] != docs[-1]:
            break
        before.append(word(tokens[i]))
    if here in FOCUS:
        value = 2.8
    elif here == "back":
        value = 0.7
    elif here in MOTION:
        value = 0.55
    elif here in PARTICLES and any(w in MOTION or w in FOCUS for w in before):
        value = 0.55
    elif here in PASSIVE:
        value = -0.4
    elif here in PARTICLES and any(w in BE or w in PASSIVE for w in before):
        value = -0.14
    else:
        value = RESTING
    return carry, value

"""Comma and clause-separator detector for layer 15's MLP down-projection, component 4898.

What it does: this component writes a strongly NEGATIVE value into the residual stream at
commas, and is near zero elsewhere. How negative depends on what the text before the comma
looks like:

- commas that close an introductory phrase ("However,", "When it rains,", "If x,") are
  weak, close to zero;
- commas in sentences that open with a subject ("The ...", "It ...") and in lists of names
  or places are strong, the most negative values in the data;
- a comma soon after another comma is weaker (recent commas suppress it);
- a comma inside brackets is weaker;
- a comma after several capitalised words (names, places, titles) is stronger;
- the first commas of a document are the strongest.

Other separators get small fixed values: full-width commas and semicolons are moderately
negative, a period right after a digit (a decimal point) is slightly negative, and an
ordinary period is slightly positive.
"""

import math
import re

READS = ()

CAPITALISED = re.compile(r"[A-Z][A-Za-z]*")
WORD = re.compile(r"[A-Za-z]+")
SENTENCE_END = re.compile(r"[.!?\n。！？]")
OPEN, CLOSE = "([{", ")]}"
INTRO = set(
    "if when while since as after before although though because once unless however "
    "therefore thus hence so but also alternatively first wait hmm then yet still moreover "
    "furthermore additionally in on at for to with by from given despite during under".split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "since": 10**6, "commas": 0, "depth": 0, "first": None}
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if prefix.position > 0 else ""

    value = 0.0
    if tok == ",":
        gap = min(carry["since"], 999)
        window = [
            t for t, d in zip(prefix.token_strings[-30:], prefix.document_ids[-30:]) if d == doc
        ]
        caps = sum(1 for t in window if CAPITALISED.fullmatch(t.strip()))
        inside = carry["depth"] > 0
        intro = carry["first"] in INTRO
        value = (
            -2.0
            - 0.5 * math.log(gap)
            + 2.3 * inside
            - 0.14 * caps
            + 0.2 * math.log1p(carry["commas"])
            + 1.9 * intro
        )
        carry["since"] = 0
        carry["commas"] += 1
    elif tok in ("，", "、"):
        value = -1.1
    elif tok == ";":
        value = -1.3
    elif tok == "." and prev.isdigit():
        value = -0.4
    elif tok == ".":
        value = 0.3

    carry["since"] += 1
    for ch in tok:
        if ch in OPEN:
            carry["depth"] += 1
        elif ch in CLOSE:
            carry["depth"] = max(0, carry["depth"] - 1)
    if SENTENCE_END.search(prefix.token_strings[-1]):
        carry["first"] = None
    elif carry["first"] is None and WORD.fullmatch(tok):
        carry["first"] = tok.lower()
    return carry, float(value)

"""Layer 15 MLP down-projection, component 4902.

What it does, in plain terms: it tracks whether a person is the one being, having or doing
something. It is strongest on a form of "be" (or get, feel, have, want, take, stay, obtain,
receive) when a person word comes just before it, as in "we were able", "I am going",
"you should be", "they got", "I need". It is pushed down when the subject is a thing ("this
is", "it needs", "it requires") and by a modal in front of "be" ("can be"). Verbs of
requirement or change (need, require, become, seem, appear) are negative with no person
nearby, and positive when a person is the subject.

The numbers are a small linear fit to the component's own activations on training rows,
with the coefficients rounded. Its values are heavy-tailed and depend on context beyond
these word classes, so the program explains only a modest part of the variance. Everything
else is predicted as 0.
"""

READS = ()

BE = {"be", "am", "is", "are", "was", "were", "been", "being", "'m", "'re"}
STATE = {"get", "got", "gets", "getting", "gotten", "feel", "felt", "feeling", "take", "took",
         "taking", "have", "has", "had", "having", "want", "wanted", "stay", "obtain", "receive"}
NEED = {"need", "needs", "needed", "require", "requires", "required", "become", "becomes",
        "became", "seem", "seems", "seemed", "appear", "appears", "appeared"}
PERSON = {"i", "you", "he", "she", "we", "they", "who", "one", "people", "me", "us", "him", "her",
          "them", "my", "our", "your"}
THING = {"this", "it", "that", "these", "those", "which", "there", "here"}
MODAL = {"can", "could", "might", "may", "cannot"}


def word(token):
    return token.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    # the three words before this one, nearest first, stopping at a document boundary
    before = []
    for j in range(2, 5):
        if len(prefix.token_ids) < j or prefix.document_ids[-j] != prefix.document_ids[-1]:
            break
        before.append(word(prefix.token_strings[-j]))
    prev = before[0] if before else ""
    person = any(w in PERSON for w in before)
    thing = prev in THING
    modal = prev in MODAL
    if cur in BE:
        value = 0.8 + 3.4 * person - 0.4 * modal - 0.8 * thing
    elif cur in STATE:
        value = 0.9 + 1.2 * person - 1.0 * thing
    elif cur in NEED:
        value = -0.8 + 2.3 * person - 1.2 * thing
    else:
        value = 0.0
    return carry, float(value)

"""Explains layers.15.mlp.down_proj:4904 of Qwen3-1.7B, a weak, noisy component.

Plain-terms reading: this component sits near zero on most tokens. Its clearest response is at
the joints of worked mathematics, where one reasoning step ends and the next begins:
  * it rises on the arrows that state a deduction (⇒, →, ≈), most strongly inside maths;
  * it rises on the words that open a new step ("Thus", "Therefore", "So", "Then", "Now", "But",
    "Hence", "Hmm", "Wait");
  * it rises on the paragraph-closing marks after a display formula (",\\n\\n", ".\\n\\n",
    ")\\n\\n", "),\\n\\n", ".$$"), and a little on other punctuation after maths;
  * it dips on code, indentation and markup, its most negative contexts.
Each of these rises with how much mathematics surrounds the token: the program carries a
decaying count of digits and maths symbols along the text (reset at each document start) and
scales the response by it.

The program reproduces that reading with a few word lists and two numbers per class. It explains
only a few percent of the variance: most of the component's activity is diffuse and is not
captured by any simple rule.
"""

READS = ()

ARROWS = {"⇒", "→", "≈", "⇔"}
CONNECTIVES = {
    "thus", "therefore", "so", "then", "now", "hence", "similarly", "but", "hmm", "wait", "okay",
}
CODE_WORDS = {"import", "###", "/bin"}
MATH_CHARS = set("0123456789=+−×÷^√≈⇒→≤≥≠")
DECAY = 0.9  # how fast the maths context fades, per token
CAP = 3.0  # the maths context is capped here

# (intercept, slope on the maths context) for each class of token
CLASS_VALUES = {
    "arrow": (-1.7, 1.4),
    "connective": (0.25, 0.75),
    "paragraph_close": (-0.1, 0.6),
    "punctuation": (-0.1, 0.15),
    "code": (-0.2, 0.02),
    "other": (-0.05, 0.03),
}


def token_class(s):
    st = s.strip()
    if st in ARROWS:
        return "arrow"
    if st.lower() in CONNECTIVES:
        return "connective"
    if any(c in s for c in "{};\t") or s.startswith("  ") or st.startswith("<") or st in CODE_WORDS:
        return "code"
    no_word = not any(c.isalnum() for c in s)
    if no_word and "\n" in s and any(c in ",.)]$}" for c in s):
        return "paragraph_close"
    if no_word and any(c in ").,$" for c in s):
        return "punctuation"
    return "other"


def step(carry, prefix, upstream):
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        math_ctx = 0.0  # a new document starts: no maths context yet
    else:
        math_ctx = carry
    s = prefix.token_strings[-1]
    math_ctx = DECAY * math_ctx + (1.0 if any(c in MATH_CHARS for c in s) else 0.0)
    intercept, slope = CLASS_VALUES[token_class(s)]
    return math_ctx, intercept + slope * min(math_ctx, CAP)

"""Layer 15 MLP neuron 4905 (component 4905 of layers.15.mlp.down_proj), read as a word-level rule.

What it is: this component is almost entirely one MLP hidden unit. Its activation is that unit's
value (its V vector is ~0.8 on unit 4905 itself), so it is negative when the text is setting up a
contrast, an exception or an alternative, and mildly positive on object/possessive pronouns.

What the program does: it looks only at the current word (and the word just before it):
  - a negation ("not", "no", "never", "n't", "не", "nicht", "不") is strongly negative when it
    follows a comma, "but", "and", "when", "though" (the "X, not Y" contrast), and mildly negative
    otherwise ("could not");
  - "without" and the limiting adverbs ("only", "just", "even", "except", ...) are negative;
  - "as", "or", "either", "than", which introduce an alternative or a role, are mildly negative;
  - object and possessive pronouns ("his", "him", "her", "my", "He", "who", "them") are mildly positive;
  - every other word predicts 0.

Limits: this explains very little. Most of the variance is in context that no word list captures
(the same word swings both ways), so the program's variance explained is about 1 percent.
"""

NEGATION = {" not", "not", " Not", "Not", " no", " never", " nicht", " не", "不", "'t", "’t"}
AFTER_CONTRAST = {",", "，", " but", " and", " when", " so", " though", " although"}
LIMITING = {" only", " just", " even", " especially", " mainly", " mostly", " particularly", " simply", " except", " almost"}
ALTERNATIVE = {" as", " or", " either", " than"}
POSSESSIVE = {" his", " him", " her", " my", " He", " who", " them"}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[prefix.position]
    before = prefix.token_strings[prefix.position - 1] if prefix.position > 0 else ""
    if word in NEGATION:
        return carry, (-2.7 if before in AFTER_CONTRAST else -0.9)
    if word == " without":
        return carry, -1.4
    if word in LIMITING:
        return carry, -0.9
    if word in ALTERNATIVE:
        return carry, -0.5
    if word in POSSESSIVE:
        return carry, 0.4
    return carry, 0.0

"""Temporal-reference detector: negative where the text is about *when*, and above all where
a year or date is about to be written or is being written.

The component's activation is mostly near zero. It goes negative in three kinds of places:
  1. Time words: month and weekday names, "ago", time units (years, days, weeks), words such as
     "before", "after", "when", "now", "during", "later", and the CJK time words 年 月 日.
  2. The space just before a date number: right after a month name (a day or year is next,
     about -14), or right after "in", "since", "born", "on" (about -7), or after a comma or
     "the" (about -1.5).
  3. The digits of a year that opens with 19 or 20: the 2nd digit (strongest for "19"), and the
     3rd and 4th digits, as the year is being written. A dash right after such a year is
     also negative (a date range).
Everywhere else the program predicts 0.
"""
READS = ()

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December", "Jan", "Feb", "Mar", "Apr", "Jun",
          "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec"}
WEEKDAYS = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"}
DAY_WORDS = {"ago": -14.0, "yesterday": -10.0, "tomorrow": -8.0, "today": -6.0,
             "tonight": -8.0, "morning": -7.0, "afternoon": -6.0, "evening": -6.0,
             "night": -4.0}
TIME_UNITS = {"week", "weeks", "month", "months", "year", "years", "decade", "decades",
              "century", "centuries", "day", "days", "hour", "hours", "minute", "minutes"}
TEMPORAL = {"before", "after", "when", "during", "now", "later", "soon", "recently", "earlier",
            "previously", "until", "since", "once", "future", "past", "early", "late", "born"}
CJK_TIME = {"年": -6.0, "月": -8.0, "日": -3.0, "今天": -6.0, "今年": -5.0, "现在": -4.0,
            "未来": -4.0, "以前": -4.0, "最近": -5.0}
DATE_CUES = {"in", "In", "at", "At", "on", "since", "born", "until", "early", "late",
             "from", "during", "between"}
PUNCT_CUES = {",", "(", "the", "of", "by"}
YEAR_START = {"19": -8.0, "20": -6.0, "18": -3.0}  # how strongly a year opening so is felt
DIGITS = set("0123456789")


def word_value(word):
    if word in CJK_TIME:
        return CJK_TIME[word]
    if word in MONTHS or word in WEEKDAYS:
        return -9.0
    if word in DAY_WORDS:
        return DAY_WORDS[word]
    if word in TIME_UNITS:
        return -5.0
    if word in TEMPORAL:
        return -3.5
    return 0.0


def step(carry, prefix, upstream):
    # The last 8 tokens, blanked where they belong to an earlier document.
    n = len(prefix.token_strings)
    lo = max(0, n - 8)
    words = [prefix.token_strings[i].strip() if prefix.document_ids[i] == prefix.document_ids[-1]
             else "" for i in range(lo, n)]
    cur, prev = words[-1], (words[-2] if n > 1 else "")
    value = word_value(cur)
    if prefix.token_strings[-1] == " ":
        if any(w in MONTHS for w in words[-7:-1]):
            value = -14.0  # a day or year is about to be written
        elif prev in DATE_CUES:
            value = -7.0  # a year is about to be written
        elif prev in PUNCT_CUES:
            value = -1.5
    elif cur in DIGITS:
        # digits of the number so far, ending with this token
        digits = ""
        for w in reversed(words):
            if w not in DIGITS or len(digits) == 4:
                break
            digits = w + digits
        if len(digits) >= 2 and digits[:2] in YEAR_START:
            value = YEAR_START[digits[:2]]
    elif cur in {"-", "–"} and len(words) >= 5:
        # a dash right after a four-digit year that starts 19 or 20 (a date range)
        year = words[-5:-1]
        if all(w in DIGITS for w in year) and "".join(year[:2]) in ("19", "20"):
            value = -5.0
    return carry, float(value)

"""Punctuation that introduces a label, value or definition pushes this component negative.

The component's activation is largely a token-level signal. It is most reliably negative on
separator punctuation: colons of every form (`Color:`, `Tests:`, `"key":`, `):`, `:=`), except
the `::` of code paths and the `://` of URLs, and assignment or arrow operators (` =`, `=>`,
`->`, `|`). Smaller negative values go to opening brackets, commas and forms of "to be"
(`is`, `are`, `were`). Month names are mildly positive. Every other token is predicted at
zero. The values are the mean activations measured on tokens of each kind. The program is
stateless: each step reads only the newest token.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

COLON_VALUE = -2.2
ASSIGN_VALUE = -1.3
BRACKET_VALUE = -0.6
COMMA_VALUE = -0.25
BE_VALUE = -0.3
MONTH_VALUE = 0.5

ASSIGN_TOKENS = {"=", ":=", "==", "=>", "->", "-->", "→", "|", "||"}
BRACKETS = {"(", "[", "{"}
BE_FORMS = {"is", "are", "was", "were", "be", "been", "being", "am"}
MONTHS = {
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    word = token.strip()
    if (":" in token or "：" in token) and "::" not in token and "//" not in token:
        value = COLON_VALUE
    elif word.endswith("=") or word in ASSIGN_TOKENS:
        value = ASSIGN_VALUE
    elif word in BRACKETS:
        value = BRACKET_VALUE
    elif word == ",":
        value = COMMA_VALUE
    elif word in BE_FORMS:
