CITATION_JOIN_VALUE = -4.5
REPEAT_SYMBOL_VALUE = -0.3
COUNT_SHORT = -0.1  # the digits so far start or spell the next number of the run
COUNT_LONG = -0.35  # ... and the run has counted up by one for at least two numbers


